// =============================================
// LOOPRA — Nodo 4: Preparar Items de Archivos
// =============================================
// Recibe el cliente de Supabase y los archivos del webhook.
// Devuelve N items (uno por archivo) con todos los datos
// necesarios para los nodos siguientes.

const client = $('🔍 Supabase: Get Cliente').item.json[0];
const webhookData = $('🔔 Webhook: Recibir Fotoshoot').item.json.body;
const files = webhookData.files || [];
const totalFiles = files.length;

if (totalFiles === 0) throw new Error('No se recibieron archivos en el payload.');
if (totalFiles > 20) throw new Error('Máximo 20 archivos por lote. Divide en múltiples llamadas.');

const SUPABASE_URL = $env.SUPABASE_URL;

// --- Lógica de Tipos de Contenido ---
// REGLA CRÍTICA: La asignación ahora se basa en el nombre del archivo
// generado por app.js (el cual lee las dimensiones para fotos).
// 'reel_...' -> REEL, 'historia_...' -> HISTORIA, 'post_...' -> POST
function assignContentType(file, index, total) {
  if (file.content_type && file.content_type.startsWith('video/')) return 'REEL';
  const name = (file.filename || '').toLowerCase();
  if (name.includes('reel_')) return 'REEL';
  if (name.includes('historia_')) return 'HISTORIA';
  return 'POST';
}

// --- Lógica de Calendario Mensual ---
function calculatePostingDate(index, total, contentType) {
  const now = new Date();
  const year = now.getFullYear();
  const month = now.getMonth();

  // Empezar desde el día siguiente
  const startDate = new Date(year, month, now.getDate() + 1);
  const daysAvailable = 28;
  const interval = Math.max(1, Math.floor(daysAvailable / total));

  let targetDate = new Date(startDate);
  targetDate.setDate(targetDate.getDate() + (index * interval));

  // Ajustar día y hora según tipo de contenido
  const dayOfWeek = targetDate.getDay(); // 0=Dom, 6=Sab

  if (contentType === 'POST') {
    // Posts en Lun/Mie/Vie a las 18:00
    const validDays = [1, 3, 5];
    let attempts = 0;
    while (!validDays.includes(targetDate.getDay()) && attempts < 7) {
      targetDate.setDate(targetDate.getDate() + 1);
      attempts++;
    }
    return { date: targetDate.toISOString().split('T')[0], time: '18:00:00' };
  } else if (contentType === 'REEL') {
    // Reels en Mar/Sab a las 20:00
    const validDays = [2, 6];
    let attempts = 0;
    while (!validDays.includes(targetDate.getDay()) && attempts < 7) {
      targetDate.setDate(targetDate.getDate() + 1);
      attempts++;
    }
    return { date: targetDate.toISOString().split('T')[0], time: '20:00:00' };
  } else {
    // Historias cualquier día a las 09:00
    return { date: targetDate.toISOString().split('T')[0], time: '09:00:00' };
  }
}

// --- Construir URL pública de Supabase Storage ---
function buildPublicUrl(filePath) {
  return `${SUPABASE_URL}/storage/v1/object/public/${filePath}`;
}

// --- Generar items de salida ---
const items = files.map((file, index) => {
  const contentType = assignContentType(file, index, totalFiles);
  const schedule = calculatePostingDate(index, totalFiles, contentType);

  return {
    json: {
      // Datos del archivo
      file_path: file.path,
      filename: file.filename,
      file_content_type: file.content_type,
      image_url_public: buildPublicUrl(file.path),
      file_index: index,
      total_files: totalFiles,

      // Datos del cliente
      client_id: client.id,
      client_name: client.name,
      industry: client.industry || 'negocio local',
      tone_of_voice: client.tone_of_voice || 'profesional y cercano',
      brand_keywords: (client.brand_keywords || []).join(', '),

      // Datos del calendario
      content_type_assigned: contentType,
      proposed_date: schedule.date,
      proposed_time: schedule.time,
      platforms: contentType === 'HISTORIA' ? ['instagram'] : ['instagram', 'tiktok'],

      // Metadata
      uploaded_by: webhookData.uploaded_by,
      session_notes: webhookData.notes || ''
    }
  };
});

return items;

