// =============================================
// LOOPRA — Nodo 6: Parsear Respuesta de IA
// =============================================
// Limpia el JSON de GPT-4o y lo combina con los
// datos del calendario del nodo anterior.

const prevData = $('📋 Preparar Items + Calendario').item.json;
const rawResponse = $json.choices?.[0]?.message?.content || '';

let aiData = {};
try {
  // Intentar parsear directamente
  aiData = JSON.parse(rawResponse);
} catch (e) {
  try {
    // Extraer JSON entre el primer { y el último }
    const match = rawResponse.match(/\{[\s\S]*\}/);
    if (match) {
      aiData = JSON.parse(match[0]);
    } else {
      throw new Error('No se encontró JSON válido en la respuesta de IA');
    }
  } catch (e2) {
    // Fallback: datos vacíos para no bloquear el flujo
    aiData = {
      copy_text: `✨ Nuevo contenido de ${prevData.client_name}`,
      hashtags: ['loopra', prevData.industry?.replace(' ', '').toLowerCase()],
      mood: 'profesional',
      description: prevData.session_notes || 'Contenido generado'
    };
  }
}

// Limpiar hashtags: asegurar que empiecen con #
const hashtags = (aiData.hashtags || []).map(h => h.startsWith('#') ? h : `#${h}`);

return [{
  json: {
    // Datos del post para Supabase
    client_id: prevData.client_id,
    status: 'PENDING_APPROVAL',
    image_url: prevData.image_url_public,
    copy_text: aiData.copy_text || '',
    hashtags: hashtags,
    proposed_date: prevData.proposed_date,
    proposed_time: prevData.proposed_time,
    platform: prevData.platforms,
    content_type: prevData.content_type_assigned,
    ai_analysis: {
      mood: aiData.mood || '',
      description: aiData.description || '',
      filename: prevData.filename,
      file_index: prevData.file_index,
      total_in_batch: prevData.total_files,
      session_notes: prevData.session_notes
    },
    uploaded_by: prevData.uploaded_by
  }
}];

